package com.greenocean.backend.trust;

import com.greenocean.backend.auth.service.RecentAuthentication;
import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Service @Transactional
public class IncidentOperations {
 private final JdbcTemplate db;private final TrustAuthority authority;private final TrustCoverage coverage;private final RecentAuthentication recent;private final boolean enabled;
 private static final List<String> STATES=List.of("DETECTED","ACKNOWLEDGED","TRIAGED","CONTAINMENT","INVESTIGATING","RECOVERY_PENDING","RECOVERING","RESOLVED","POST_INCIDENT_REVIEW","CLOSED");
 private static final Set<String> KINDS=Set.of("DATA_EXPOSURE","CREDENTIAL_COMPROMISE","DATABASE_OUTAGE","EMAIL_OUTAGE","PAYMENT_CALLBACK","REFUND_DELAY","STAFFING_GAP","MEDIA_INTERRUPTION","VISIBILITY_REGRESSION","KEY_CONFIGURATION","SERVICE_FAILURE","BACKUP_FAILURE");
 public IncidentOperations(JdbcTemplate db,TrustAuthority authority,TrustCoverage coverage,RecentAuthentication recent,@Value("${greenocean.operations.enabled:false}")boolean enabled){this.db=db;this.authority=authority;this.coverage=coverage;this.recent=recent;this.enabled=enabled;}
 public void require(UUID who,UUID sid,String domain){if(!enabled)throw new ForbiddenException("Incident operations await approved purpose and actual operating ownership");authority.require(who,sid,domain);}
 public static void evidence(String reference){if(reference==null||!reference.matches("[A-Z][A-Z0-9_-]{2,30}:[a-zA-Z0-9._-]{1,120}"))throw new IllegalArgumentException("Use a restricted opaque evidence reference, not private narrative or a URL");}
 int version(UUID who,UUID sid){var rows=db.queryForList("SELECT token_version FROM user_sessions WHERE id=? AND user_id=? AND revoked_at IS NULL FOR SHARE",sid,who);if(rows.isEmpty())throw new UnauthorizedException("Sign in again before privileged operations");return((Number)rows.getFirst().get("token_version")).intValue();}
 void staffed(UUID who,String domain){if(!coverage.live(domain,who))throw new ConflictException("Current acknowledged staffed coverage is required; no response time is promised");}
 Map<String,Object> lock(UUID who,UUID sid,UUID id){var rows=db.queryForList("SELECT domain FROM operation_incidents WHERE id=?",id);if(rows.isEmpty())throw new NotFoundException("Incident unavailable");require(who,sid,(String)rows.getFirst().get("domain"));return db.queryForMap("SELECT * FROM operation_incidents WHERE id=? FOR UPDATE",id);}
 void exact(Map<String,Object> row,long revision){if(((Number)row.get("revision")).longValue()!=revision)throw new ConflictException("Reload the exact current incident revision");}
 private void event(UUID who,UUID id,long revision,String from,String to,String reference){db.update("INSERT INTO operation_incident_events(incident_id,revision,actor_id,from_state,to_state,evidence_reference) VALUES(?,?,?,?,?,?)",id,revision,who,from,to,reference);}
 public UUID detect(UUID who,UUID sid,String domain,String kind,String severity,UUID dedup,String reference){require(who,sid,domain);evidence(reference);if(!KINDS.contains(kind)||!Set.of("SEV1","SEV2","SEV3","SEV4").contains(severity)||dedup==null)throw new IllegalArgumentException("Choose a fixed operational kind, severity and retry key");
  db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","incident:"+domain+":"+dedup);var old=db.queryForList("SELECT id,kind,severity,evidence_reference FROM operation_incidents WHERE domain=? AND dedup_key=?",domain,dedup);if(!old.isEmpty()){var r=old.getFirst();if(!kind.equals(r.get("kind"))||!severity.equals(r.get("severity"))||!reference.equals(r.get("evidence_reference")))throw new ConflictException("Retry key belongs to different incident evidence");return(UUID)r.get("id");}authority.budget(who,"INCIDENT_DETECTED",20);UUID id=UUID.randomUUID();db.update("INSERT INTO operation_incidents(id,domain,kind,severity,created_by,evidence_reference,dedup_key) VALUES(?,?,?,?,?,?,?)",id,domain,kind,severity,who,reference,dedup);event(who,id,1,null,"DETECTED",reference);return id;
 }
 public List<Map<String,Object>> queue(UUID who,UUID sid,String domain){require(who,sid,domain);return db.queryForList("SELECT id,domain,kind,severity,state,revision,owner_id,evidence_reference,created_at,updated_at FROM operation_incidents WHERE domain=? ORDER BY created_at DESC,id DESC LIMIT 50",domain);}
 public void classify(UUID who,UUID sid,UUID id,long revision,String kind,String severity,String reference){evidence(reference);var r=lock(who,sid,id);exact(r,revision);staffed(who,(String)r.get("domain"));if(!KINDS.contains(kind)||!Set.of("SEV1","SEV2","SEV3","SEV4").contains(severity))throw new IllegalArgumentException("Choose a fixed operational classification");if(!Set.of("DETECTED","ACKNOWLEDGED","TRIAGED","CONTAINMENT","INVESTIGATING").contains(r.get("state")))throw new ConflictException("Recovery or completed incidents require a separately evidenced follow-up incident");if(r.get("owner_id")!=null&&!who.equals(r.get("owner_id")))throw new ForbiddenException("Only the current responsible owner may revise classification");db.update("UPDATE operation_incidents SET kind=?,severity=?,revision=revision+1,evidence_reference=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",kind,severity,reference,id);event(who,id,revision+1,(String)r.get("state"),(String)r.get("state"),reference);}
 public void claimUnavailable(UUID who,UUID sid,UUID id,long revision,String reference){evidence(reference);var r=lock(who,sid,id);exact(r,revision);String domain=(String)r.get("domain");staffed(who,domain);if(!authority.has(who,"TRUST_PLATFORM"))throw new ForbiddenException("Current explicit staffing authority required");if(r.get("owner_id")==null||coverage.live(domain,(UUID)r.get("owner_id"))||"CLOSED".equals(r.get("state")))throw new ConflictException("Use initial acknowledgement or a genuinely unavailable open-incident owner");db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","trust-assignment:"+who);if(!coverage.canAssign(domain,who))throw new ConflictException("No current staffed capacity for takeover");String next="RECOVERY_PENDING".equals(r.get("state"))?"INVESTIGATING":(String)r.get("state");db.update("UPDATE operation_incidents SET owner_id=?,state=?,revision=revision+1,evidence_reference=?,updated_at=CURRENT_TIMESTAMP,recovery_author=NULL,recovery_session=NULL,recovery_version=NULL,recovery_expires_at=NULL,recovery_reviewer=NULL WHERE id=?",who,next,reference,id);event(who,id,revision+1,(String)r.get("state"),next,reference);}
 public Map<String,Object> detail(UUID who,UUID sid,UUID id){var r=lock(who,sid,id);r.remove("recovery_session");r.remove("recovery_version");return Map.of("incident",r,"timeline",db.queryForList("SELECT revision,from_state,to_state,evidence_reference,created_at FROM operation_incident_events WHERE incident_id=? ORDER BY revision LIMIT 100",id),"controls",db.queryForList("SELECT id,control,action,incident_revision,expires_at,approved_at,author_id=? AS own_proposal FROM operation_containment WHERE incident_id=? ORDER BY created_at DESC LIMIT 50",who,id));}
 public void transition(UUID who,UUID sid,UUID id,long revision,String next,String reference){evidence(reference);var r=lock(who,sid,id);exact(r,revision);String domain=(String)r.get("domain"),old=(String)r.get("state");if(!STATES.contains(next)||STATES.indexOf(next)!=STATES.indexOf(old)+1)throw new ConflictException("Follow the accountable incident lifecycle");staffed(who,domain);
  if("ACKNOWLEDGED".equals(next)){db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","trust-assignment:"+who);if(!coverage.canAssign(domain,who))throw new ConflictException("No current staffed capacity for incident ownership");db.update("UPDATE operation_incidents SET owner_id=? WHERE id=?",who,id);}
  else if("RECOVERING".equals(next)){if(who.equals(r.get("recovery_author"))||r.get("recovery_author")==null||r.get("recovery_expires_at")==null||!((java.sql.Timestamp)r.get("recovery_expires_at")).toInstant().isAfter(java.time.Instant.now()))throw new ForbiddenException("Fresh independent recovery authorization required");UUID author=(UUID)r.get("recovery_author"),session=(UUID)r.get("recovery_session");require(author,session,domain);staffed(author,domain);if(!Objects.equals(r.get("recovery_version"),version(author,session)))throw new ConflictException("Recovery proposing session changed");db.update("UPDATE operation_incidents SET recovery_reviewer=? WHERE id=?",who,id);}
  else if(!who.equals(r.get("owner_id")))throw new ForbiddenException("Current acknowledged incident owner must record this action");
  if("RESOLVED".equals(next)&&db.queryForObject("SELECT count(*) FROM operation_containment c WHERE c.incident_id=? AND c.approved_at IS NOT NULL AND c.action='PAUSE' AND c.revoked_at IS NULL AND NOT EXISTS(SELECT 1 FROM operation_containment n WHERE n.incident_id=c.incident_id AND n.control=c.control AND n.target_user IS NOT DISTINCT FROM c.target_user AND n.approved_at>c.approved_at AND n.approved_at IS NOT NULL AND n.action='RESUME')",Integer.class,id)>0)throw new ConflictException("Active containment needs an independently approved recovery decision before resolution");
  db.update("UPDATE operation_incidents SET state=?,revision=revision+1,evidence_reference=?,updated_at=CURRENT_TIMESTAMP,recovery_author=CASE WHEN ?='RECOVERY_PENDING' THEN ? ELSE recovery_author END,recovery_session=CASE WHEN ?='RECOVERY_PENDING' THEN ? ELSE recovery_session END,recovery_version=CASE WHEN ?='RECOVERY_PENDING' THEN ? ELSE recovery_version END,recovery_expires_at=CASE WHEN ?='RECOVERY_PENDING' THEN CURRENT_TIMESTAMP+INTERVAL '15 minutes' ELSE recovery_expires_at END WHERE id=?",next,reference,next,who,next,sid,next,version(who,sid),next,id);event(who,id,revision+1,old,next,reference);
 }
 private static String controlDomain(String control){return switch(control){case"LISTENER_NEW","LISTENER_QUEUE"->"LISTENER";case"CLINIC_BOOKING","CLINIC_MEDIA"->"CLINIC";case"PAYMENT_CAPTURE"->"FINANCE";case"EDUCATION_PUBLICATION"->"EDUCATION";case"ACCOUNT_RESTRICTION"->"ACCOUNT";default->throw new IllegalArgumentException("Choose an allowlisted containment control");};}
 public UUID propose(UUID who,UUID sid,UUID incident,long revision,String control,String action,UUID target,String reference){evidence(reference);var r=lock(who,sid,incident);exact(r,revision);String domain=(String)r.get("domain");if(!domain.equals(controlDomain(control))&&!domain.equals("PLATFORM"))throw new ForbiddenException("Containment is limited to the incident service purpose");require(who,sid,controlDomain(control));staffed(who,domain);if(!who.equals(r.get("owner_id")))throw new ForbiddenException("The assigned incident owner must propose containment");if(!Set.of("PAUSE","RESUME").contains(action)||("ACCOUNT_RESTRICTION".equals(control)!=(target!=null)))throw new IllegalArgumentException("Choose a bounded source control");if("ACCOUNT_RESTRICTION".equals(control)&&"RESUME".equals(action))throw new ForbiddenException("Account reactivation requires its existing independent account workflow");if("RESUME".equals(action)&&!Set.of("RECOVERING","RESOLVED").contains(r.get("state")))throw new ConflictException("Independent incident recovery must precede reopening admissions");authority.budget(who,"CONTAINMENT_PROPOSED",20);UUID id=UUID.randomUUID();db.update("INSERT INTO operation_containment(id,incident_id,domain,control,target_user,action,author_id,author_session,author_version,incident_revision,evidence_reference) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,incident,domain,control,target,action,who,sid,version(who,sid),revision,reference);return id;}
 public void approve(UUID who,UUID sid,UUID incident,UUID proposal,long revision){var hint=db.queryForList("SELECT author_id FROM operation_containment WHERE id=? AND incident_id=?",proposal,incident);if(hint.isEmpty())throw new NotFoundException("Containment proposal unavailable");db.queryForList("SELECT id FROM users WHERE id=? FOR SHARE",hint.getFirst().get("author_id"));var r=lock(who,sid,incident);exact(r,revision);var c=db.queryForMap("SELECT *,expires_at>CURRENT_TIMESTAMP AS live FROM operation_containment WHERE id=? AND incident_id=? FOR UPDATE",proposal,incident);String domain=(String)r.get("domain"),control=(String)c.get("control");require(who,sid,controlDomain(control));staffed(who,domain);if(who.equals(c.get("author_id")))throw new ForbiddenException("A second independent operator must authorize containment");if(!Boolean.TRUE.equals(c.get("live"))||c.get("approved_at")!=null||c.get("revoked_at")!=null||((Number)c.get("incident_revision")).longValue()!=revision)throw new ConflictException("Review a fresh proposal against the current incident revision");UUID author=(UUID)c.get("author_id"),authorSid=(UUID)c.get("author_session");require(author,authorSid,domain);require(author,authorSid,controlDomain(control));staffed(author,domain);if(!Objects.equals(c.get("author_version"),version(author,authorSid)))throw new ConflictException("Proposing session changed");
  db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","containment:"+control);db.update("UPDATE operation_containment SET approved_at=clock_timestamp(),reviewer_id=? WHERE id=?",who,proposal);if("ACCOUNT_RESTRICTION".equals(control)){UUID target=(UUID)c.get("target_user");if(target.equals(author)||target.equals(who))throw new ForbiddenException("Independent account restriction required");db.update("UPDATE users SET status='SUSPENDED',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='ACTIVE'",target);db.update("UPDATE user_sessions SET revoked_at=CURRENT_TIMESTAMP,token_version=token_version+1 WHERE user_id=? AND revoked_at IS NULL",target);}authority.audit(who,incident,"CONTAINMENT_INDEPENDENTLY_APPROVED");
 }
}
